39	func (c *instanceStatsCache) set(v *v1pb.InstanceStats, ttl time.Duration) {
40		c.mu.Lock()
41		defer c.mu.Unlock()
42		c.value = v
43		c.expiry = time.Now().Add(ttl)
44	}
