71	// computeInstanceStats runs all stat subqueries in parallel and assembles the result.
72	// Per-subtask failures degrade to -1 sentinel values; only a total failure (every
73	// subtask errored) is propagated as an error.
74	func (s *APIV1Service) computeInstanceStats(ctx context.Context) (*v1pb.InstanceStats, error) {
75		stats := &v1pb.InstanceStats{
76			Database: &v1pb.InstanceStats_DatabaseStats{
77				Driver:    s.Profile.Driver,
78				SizeBytes: -1,
79			},
80			LocalStorageBytes: -1,
81			GeneratedTime:     timestamppb.Now(),
82		}
83	
84		type result struct {
85			name string
86			err  error
87		}
88		var (
89			mu      sync.Mutex
90			results []result
91			record  = func(name string, err error) {
92				mu.Lock()
93				results = append(results, result{name, err})
94				mu.Unlock()
95			}
96		)
97	
98		g, gctx := errgroup.WithContext(ctx)
99	
100		g.Go(func() error {
101			size, err := s.Store.GetDriver().GetDatabaseSize(gctx)
102			if err != nil {
103				record("database_size", err)
104				return nil
105			}
106			stats.Database.SizeBytes = size
107			return nil
108		})
109	
110		g.Go(func() error {
111			size, err := walkLocalStorage(s.Profile.Data)
112			if err != nil {
113				record("local_storage", err)
114				return nil
115			}
116			stats.LocalStorageBytes = size
117			return nil
118		})
119	
120		_ = g.Wait()
121	
122		for _, r := range results {
123			slog.Warn("instance stats subtask failed", slog.String("subtask", r.name), slog.String("err", r.err.Error()))
124		}
125	
126		const totalSubtasks = 2
127		if len(results) == totalSubtasks {
128			return nil, errors.New("all instance stats subtasks failed")
129		}
130		return stats, nil
131	}
